+}
+
+static int transfer(int fd, void *buffer, size_t length, int sending) {
+  size_t done = 0;
+  while (done < length) {
+    ssize_t n = sending ? write(fd, (char *)buffer + done, length - done)
+                        : read(fd, (char *)buffer + done, length - done);
+    if (n < 0 && errno == EINTR) continue;
+    if (n <= 0) return -1;
+    done += (size_t)n;
+  }
+  return 0;
+}
