+#[test]
+fn vfork_return_restores_the_same_actual_frame() {
+    exercise(2);
+}"},{"sha":"b3c680b41bfdc715a7984bd8713d2d8d222c1dfe","filename":"experimental/reverie-sabre/vendor/sabre/arch/x86_64/handle_syscall_loader.s","status":"modified","additions":13,"deletions":4,"changes":17,"blob_url":"https://github.com/rrnewton/reverie/blob/61098967f47041f96a43995f5272412cf9fe5761/experimental%2Freverie-sabre%2Fvendor%2Fsabre%2Farch%2Fx86_64%2Fhandle_syscall_loader.s","raw_url":"https://github.com/rrnewton/reverie/raw/61098967f47041f96a43995f5272412cf9fe5761/experimental%2Freverie-sabre%2Fvendor%2Fsabre%2Farch%2Fx86_64%2Fhandle_syscall_loader.s","contents_url":"https://api.github.com/repos/rrnewton/reverie/contents/experimental%2Freverie-sabre%2Fvendor%2Fsabre%2Farch%2Fx86_64%2Fhandle_syscall_loader.s?ref=61098967f47041f96a43995f5272412cf9fe5761","patch":"@@ -15,7 +15,13 @@ handle_syscall_loader:
